// Molina and her pond friends as SVG pixel art. Molina is built from the same
// 32x32 arrays as her desktop pet (molina/sprites.py in github.com/DeyDom001/Molina).
// The friends are original pixel art, drawn here as rows of letters.

// Colors by letter. Molina: o outline, b body, l belly, c cheeks, g gills, t gill tips,
// e highlights. Friends: y/u fish, k/s/h snail, j jellyfish, w white, n/m/p turtle,
// x orca, r/q manta, z seahorse, v/d pufferfish, a starfish, i shrimp, P/Q octopus,
// G/H eel, S/T squid, N sardine, W whale shadow, K striped fish.
const PALETTE: Record<string, string> = {
  o: '#141413', b: '#F2B8B2', l: '#FADBD6', c: '#D97757', g: '#D97757', t: '#E8A387', e: '#F0EEE6',
  y: '#F6C85F', u: '#6FC3DF', k: '#9DB7A8', s: '#D9A05B', h: '#A8693A', j: '#C9A0D9', w: '#F0EEE6',
  n: '#6E9C5A', m: '#4E7A44', p: '#A9C79A', x: '#1F2228', r: '#4A6375', q: '#9DB4C0', z: '#F2A65A',
  v: '#F0B860', d: '#FBE7C0', a: '#E0806A', i: '#F4A09A',
  P: '#B57BD6', Q: '#D9A7EE', G: '#7FA36A', H: '#C8D98A', S: '#E7C6D9', T: '#C98FB0',
  N: '#7F95A6', W: '#0F2E3A', K: '#F08A3C',
}
const N = 32

// Left half of a row + its mirror image = a symmetric row.
const mirror = (rows: string[]) => rows.map(r => r + [...r].reverse().join(''))

const BODY = mirror([
  '...........ooooo', '.........oobbbbb', '.......oobbbbbbb', '......obbbbbbbbb', '......obbbbbbbbb',
  '.....obbbbbbbbbb', '.....obbbbbbbbbb', '.....obbbbbbbbbb', '.....obbbbbbbbbb', '.....obbbbbbbbbb',
  '.....obbbbbbbbbb', '......obbbbbbbbb', '......obbbbbbbbb', '.......oobbbbbbb', '.........obbbbbb',
  '........obbbllll', '.......obbbbllll', '......obbobbllll', '.......oobbbllll', '........obbbllll',
  '........obbbbbbb', '.........obboooo', '.........oooo...',
])
const GILLS = [
  '..t.......', '.tgt......', '..tgt.....', '...tgg....', '....tggg..', '......gggg', '..........', 'tt........',
  'tgggggg...', 'ttgggggggg', 'tt........', '..........', '...ggggggg', '.tgggt....', 'tgt.......', '.t........',
]
const TAIL = ['......t.', '.....tgt', '....obbo', '...obbo.', '..obbo..', 'bbbbo...', 'bbbo....', 'ooo.....']
const ZED = ['eeee', '..e.', '.e..', 'eeee']
const SPARK = ['.t.', 'tet', '.t.']
const EYES: Record<string, string[]> = {
  open: ['oe', 'oo', 'oo'], left: ['eo', 'oo', 'oo'], blink: ['bb', 'bb', 'oo'], tired: ['bb', 'oo', 'oe'],
}
const MOUTHS: Record<string, [number, number][]> = {
  line: [[15, 16], [16, 16]],
  smile: [[14, 15], [15, 16], [16, 16], [17, 15]],
  open: [[15, 16], [16, 16], [15, 17], [16, 17]],
}

// --- Pond friends (fish face left; turtle, orca, manta and seahorse as drawn).
const FISH = ['..oooo....', '.oyyyyo.oo', 'oyoyyyyoyo', '.oyyyyo.oo', '..oooo....']
